-- Migration: initial_schema
-- Created: 2026-05-23
--
-- Snapshot of src/lib/db/schema.sql at the time the migration system was
-- introduced. Made idempotent (CREATE TABLE IF NOT EXISTS / CREATE INDEX
-- IF NOT EXISTS) so the migration runner can safely re-apply against a
-- database that was already populated via the docker-entrypoint-initdb.d
-- auto-init path on first volume creation.
--
-- Do NOT edit this file after it has been applied to any environment.
-- For schema changes, write a NEW migration (NNN_<description>.sql).

-- ═══════════════════════════════════════════════
-- KLAMMER MONITOR - Database Schema
-- PostgreSQL 16 + pgvector + TimescaleDB
-- ═══════════════════════════════════════════════

-- Extensions
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "vector";

-- ─── Organizations ───
CREATE TABLE IF NOT EXISTS organizations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  plan TEXT DEFAULT 'analyst',
  stripe_customer_id TEXT,
  stripe_subscription_id TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ─── Users ───
CREATE TABLE IF NOT EXISTS users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id UUID REFERENCES organizations(id) ON DELETE SET NULL,
  email TEXT UNIQUE NOT NULL,
  name TEXT,
  role TEXT DEFAULT 'analyst',
  focus_areas TEXT[] DEFAULT '{}',
  preferences JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_org ON users(org_id);

-- ─── Intelligence Items ───
CREATE TABLE IF NOT EXISTS intelligence_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source TEXT NOT NULL,
  source_id TEXT,
  category TEXT,
  severity TEXT DEFAULT 'info',
  title TEXT NOT NULL,
  summary TEXT,
  url TEXT,
  published_at TIMESTAMPTZ,
  geo_lat DOUBLE PRECISION,
  geo_lon DOUBLE PRECISION,
  geo_name TEXT,
  entities TEXT[] DEFAULT '{}',
  tags TEXT[] DEFAULT '{}',
  raw_data JSONB,
  embedding VECTOR(1536),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(source, source_id)
);

CREATE INDEX IF NOT EXISTS idx_items_source_time ON intelligence_items(source, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_items_severity ON intelligence_items(severity, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_items_geo ON intelligence_items(geo_lat, geo_lon) WHERE geo_lat IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_items_entities ON intelligence_items USING GIN(entities);
CREATE INDEX IF NOT EXISTS idx_items_tags ON intelligence_items USING GIN(tags);
CREATE INDEX IF NOT EXISTS idx_items_created ON intelligence_items(created_at DESC);

-- Vector similarity search index
CREATE INDEX IF NOT EXISTS idx_items_embedding ON intelligence_items
  USING hnsw(embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64);

-- ─── Agent Events (audit trail) ───
CREATE TABLE IF NOT EXISTS agent_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  trigger_type TEXT NOT NULL,
  trigger_source TEXT,
  trigger_data JSONB,
  task TEXT NOT NULL,
  tool_calls JSONB DEFAULT '[]',
  response_text TEXT,
  model TEXT NOT NULL,
  tokens_input INT,
  tokens_output INT,
  duration_ms INT,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_agent_events_user ON agent_events(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_events_trigger ON agent_events(trigger_type, created_at DESC);

-- ─── Agent Memory ───
CREATE TABLE IF NOT EXISTS agent_memory (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  topic TEXT NOT NULL,
  content TEXT NOT NULL,
  importance TEXT DEFAULT 'medium',
  embedding VECTOR(1536),
  access_count INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  last_accessed_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_memory_topic ON agent_memory(user_id, topic);
CREATE INDEX IF NOT EXISTS idx_memory_importance ON agent_memory(importance, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_memory_embedding ON agent_memory
  USING hnsw(embedding vector_cosine_ops);

-- ─── Agent Briefs ───
CREATE TABLE IF NOT EXISTS agent_briefs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_event_id UUID REFERENCES agent_events(id) ON DELETE SET NULL,
  topic TEXT NOT NULL,
  format TEXT NOT NULL,
  headline TEXT NOT NULL,
  confidence TEXT,
  content JSONB NOT NULL,
  published BOOLEAN DEFAULT FALSE,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_briefs_user ON agent_briefs(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_briefs_published ON agent_briefs(published, created_at DESC);

-- ─── Approval Queue ───
CREATE TABLE IF NOT EXISTS approval_queue (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_event_id UUID REFERENCES agent_events(id) ON DELETE CASCADE,
  action_type TEXT NOT NULL,
  action_input JSONB NOT NULL,
  agent_reasoning TEXT,
  urgency TEXT NOT NULL DEFAULT 'medium',
  status TEXT DEFAULT 'pending',
  decided_by UUID REFERENCES users(id) ON DELETE SET NULL,
  decided_at TIMESTAMPTZ,
  feedback TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  expires_at TIMESTAMPTZ DEFAULT (NOW() + INTERVAL '24 hours')
);

CREATE INDEX IF NOT EXISTS idx_approval_status ON approval_queue(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_approval_user ON approval_queue(decided_by);

-- ─── Alert Rules ───
CREATE TABLE IF NOT EXISTS alert_rules (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  conditions JSONB NOT NULL,
  severity TEXT NOT NULL DEFAULT 'medium',
  channels TEXT[] DEFAULT '{dashboard}',
  enabled BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_alert_rules_user ON alert_rules(user_id, enabled);

-- ─── Alert History ───
CREATE TABLE IF NOT EXISTS alert_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  rule_id UUID REFERENCES alert_rules(id) ON DELETE SET NULL,
  trigger_data JSONB,
  severity TEXT NOT NULL DEFAULT 'medium',
  title TEXT,
  summary TEXT,
  acknowledged BOOLEAN DEFAULT FALSE,
  acknowledged_by UUID REFERENCES users(id) ON DELETE SET NULL,
  acknowledged_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_alert_history_time ON alert_history(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_alert_history_ack ON alert_history(acknowledged, created_at DESC);

-- ─── Custom Monitors ───
CREATE TABLE IF NOT EXISTS monitors (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  keywords TEXT[] NOT NULL,
  color TEXT DEFAULT '#44ff88',
  geo_lat DOUBLE PRECISION,
  geo_lon DOUBLE PRECISION,
  notify_on_match BOOLEAN DEFAULT TRUE,
  map_pin BOOLEAN DEFAULT TRUE,
  enabled BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_monitors_user ON monitors(user_id, enabled);
CREATE INDEX IF NOT EXISTS idx_monitors_keywords ON monitors USING GIN(keywords);

-- ─── Market Data (time-series) ───
CREATE TABLE IF NOT EXISTS market_data (
  time TIMESTAMPTZ NOT NULL,
  symbol TEXT NOT NULL,
  open NUMERIC,
  high NUMERIC,
  low NUMERIC,
  close NUMERIC,
  volume BIGINT,
  source TEXT DEFAULT 'polygon'
);

-- TimescaleDB hypertable (will fail gracefully if extension not available)
DO $$
BEGIN
  PERFORM create_hypertable('market_data', 'time', if_not_exists => TRUE);
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'TimescaleDB not available, using regular table for market_data';
END
$$;

CREATE INDEX IF NOT EXISTS idx_market_symbol_time ON market_data(symbol, time DESC);

-- ─── Conversation Exchanges ───
CREATE TABLE IF NOT EXISTS conversation_exchanges (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id TEXT NOT NULL,
  user_message TEXT NOT NULL,
  assistant_response TEXT NOT NULL,
  tool_calls JSONB DEFAULT '[]',
  tool_count INT DEFAULT 0,
  origin TEXT NOT NULL DEFAULT 'agent',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_exchanges_user_time ON conversation_exchanges(user_id, created_at DESC);

-- ─── Auto-expire approval queue entries ───
CREATE OR REPLACE FUNCTION expire_approvals() RETURNS void AS $$
BEGIN
  UPDATE approval_queue
  SET status = 'expired'
  WHERE status = 'pending' AND expires_at < NOW();
END;
$$ LANGUAGE plpgsql;
